using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns a URL for Toncoin withdrawal from the current user's account. The user must have at least 10 toncoins to withdraw
    /// and can withdraw up to 100000 Toncoins in one transaction
    /// </summary>
    public Task<TdLib.TdApi.Objects.HttpUrl> GetTonWithdrawalUrlAsync(string password = default)
    {

           using var activity =  StartCallActivity("GetTonWithdrawalUrlAsync", typeof(GetTonWithdrawalUrl).FullName ?? "GetTonWithdrawalUrlAsync");

           try
           {
             return client.GetTonWithdrawalUrlAsync(password);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
